def choose_move(observation):
    def _pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def _sgn(a, b):
        return 0 if a == b else (1 if a > b else -1)

    def _move_toward(src, dst):
        sx, sy = src
        tx, ty = dst
        return [_sgn(sx, tx), _sgn(sy, ty)]

    def _dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    env = observation.get("environment_name", "resource_collection")
    sx, sy = _pos(observation.get("self_position", observation.get("agent_position", (0, 0))))
    ox, oy = _pos(observation.get("opponent_position", observation.get("enemy_position", (sx, sy))))
    w = observation.get("grid_width", observation.get("width", 0))
    h = observation.get("grid_height", observation.get("height", 0))

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return _move_toward((sx, sy), (ox, oy))
        corners = [(0, 0), (0, max(0, h - 1)), (max(0, w - 1), 0), (max(0, w - 1), max(0, h - 1))]
        target = corners[0]
        best = -1
        for c in corners:
            d = _dist(c, (ox, oy))
            if d > best:
                best = d
                target = c
        return _move_toward((sx, sy), target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        if targets:
            best = targets[0]
            best_d = _dist(_pos(best), (sx, sy))
            for t in targets[1:]:
                p = _pos(t)
                d = _dist(p, (sx, sy))
                if d < best_d:
                    best_d = d
                    best = t
            return _move_toward((sx, sy), _pos(best))
        if w and h:
            return _move_toward((sx, sy), (w // 2, h // 2))
        return [0, 0]

    resources = observation.get("resources") or observation.get("resource_positions") or []
    if resources:
        best = resources[0]
        best_d = _dist(_pos(best), (sx, sy))
        for r in resources[1:]:
            p = _pos(r)
            d = _dist(p, (sx, sy))
            if d < best_d:
                best_d = d
                best = r
        dx, dy = _move_toward((sx, sy), _pos(best))
        if (sx + dx, sy + dy) == (ox, oy):
            away = _move_toward((ox, oy), (sx, sy))
            if away != [0, 0]:
                return away
        return [dx, dy]

    if w and h:
        return _move_toward((sx, sy), (w // 2, h // 2))
    return _move_toward((sx, sy), (ox, oy))

